export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

export const Head: HeadFC = ({ location, pageContext }) => {
  const language = (pageContext as { language?: string }).language || "fr";
  const pathname = language === "fr" ? "/fr/contact/" : "/en/contact/";
  const alternates = [
    { hrefLang: "fr", href: "https://riano.ca/fr/contact/" },
    { hrefLang: "en", href: "https://riano.ca/en/contact/" },
    { hrefLang: "x-default", href: "https://riano.ca/fr/contact/" },
  ];

  return (
    <SEO
      data={info}
      titleKey="seo.contact.metaTitle"
      descriptionKey="seo.contact.metaDescription"
      pathname={pathname}
      currentPathname={location.pathname}
      language={language}
      alternates={alternates}
      schemaType="ProfessionalService"
    />
  );
};
